#define ULTIMATE_ERR_NOT_SUPPORTED    4  /* Target or command not implemented by this firmware */
#define ULTIMATE_ERR_INVALID_ARGUMENT 5  /* Bad argument supplied by the caller */
#define ULTIMATE_ERR_IO               6  /* File system / network I/O failure */
#define ULTIMATE_ERR_DEVICE           7  /* Target reported a failure status */
#define ULTIMATE_ERR_TRUNCATED        8  /* Reply did not fit in the caller's buffer */
#define ULTIMATE_ERR_ABORTED          9  /* Command was aborted */
#define ULTIMATE_END                  10  /* No more entries: the end of a directory, not a failure */
#define ULTIMATE_ERR_COUNT            11  /* Number of codes above, for a table that maps them */

