/* ---- SDK memory footprint ---- */
/* How much RAM the core needs, and where. All of it is placeable: see */
/* UCI_ZP and UCI_VARS in docs/asm-abi.md. */
#define UCI_ZP_SIZE   4  /* zero page bytes the core needs */
#define UCI_VARS_SIZE 125  /* non-zero-page bytes the whole SDK needs */

/* ---- ASCII literals ---- */
/* Bytes that come off the wire are always written numerically. An */
/* assembler charmap, or a compiler's idea of the target character set, */
/* must never reach them: cc65 turns "NO TARGET" into PETSCII, which */
/* silently stops matching what the Ultimate sends. */
#define UCI_ASCII_ZERO  0x30  /* '0' */
#define UCI_ASCII_NINE  0x39  /* '9' */
#define UCI_ASCII_COMMA 0x2C  /* ',' */
#define UCI_ASCII_SPACE 0x20  /* ' ' */

/* ---- Status string families ---- */
/* Targets do not agree on how status is encoded; the SDK picks a decoder */
/* per target. */
#define UCI_STATUS_FMT_DECIMAL2 0  /* 'NN,TEXT' - DOS, Network, Control */
#define UCI_STATUS_FMT_DECIMAL3 1  /* 'NNN TEXT' - HTTP */
#define UCI_STATUS_FMT_BINARY   2  /* single binary byte - SoftwareIEC */
#define UCI_STATUS_FMT_NONE     3  /* target sends no status */

/* ---- Protocol strings ---- */
/*
 * Protocol strings are emitted as explicit byte lists, never as C string
 * literals. cc65 translates literals into the target character set, so
 * "NO TARGET" compiled for the C64 becomes PETSCII and stops matching the
 * ASCII the Ultimate actually sends. Use them as:
 *
 *     static const uint8_t marker[] = { UCI_STR_NO_TARGET_BYTES };
 */
/* UCI_STR_NO_TARGET = "NO TARGET": Reply of the built-in placeholder target: this target ID is not implemented. */
#define UCI_STR_NO_TARGET_BYTES 0x4E, 0x4F, 0x20, 0x54, 0x41, 0x52, 0x47, 0x45, 0x54
#define UCI_STR_NO_TARGET_LEN 9
/* UCI_STR_STATUS_OK = "00,OK": Canonical success status of the decimal2 family. */
#define UCI_STR_STATUS_OK_BYTES 0x30, 0x30, 0x2C, 0x4F, 0x4B
#define UCI_STR_STATUS_OK_LEN 5

#endif /* ULTIMATE_UCI_PROTOCOL_H */
